    "id": "geral-180q-16",
    "numero": 16,
    "macroModuloId": "M12",
    "submoduloId": "12.1",
    "contexto": "Text I — AI in parliament (texto autoral HNC)\n\nLegislatures produce large volumes of unstructured text, from plenary transcripts to committee amendments. AI tools can help staff search this material, compare drafts and prepare briefings. Their usefulness, however, depends on reliable records and human-in-the-loop oversight. Trained professionals must review outputs, check sources and protect confidential information. Tools may speed up parts of the work, but they do not transfer responsibility away from public institutions. Risks include inaccurate summaries, biased output and improper disclosure. Introducing a system therefore calls for evaluation and clear rules, not either unconditional trust or a blanket ban.",
    "item": "Com base no Text I, o objetivo primordial do texto é apresentar o potencial transformador da inteligência artificial nas assembleias legislativas, enfatizando a imperiosa necessidade de supervisão humana para mitigar riscos operacionais e éticos.",
    "gabarito": "C",
    "justificativa": "CERTO. O texto articula aplicações úteis da IA com revisão profissional: localizar material, comparar versões e preparar informações são possibilidades, enquanto conferir fontes e proteger dados continuam sob responsabilidade humana. Essa combinação sustenta a ideia central; listar apenas benefícios ou apenas riscos perde a tese.",
    "armadilhaBanca": "Relacionar tese, possibilidades e ressalvas.",
    "dificuldade": "facil",
    "fonteOriginal": {
      "tipo": "inedita",
      "verificado": false,
      "descricao": "Item autoral HNC sobre texto de apoio reconstruído editorialmente; não é transcrição de questão oficial."
    },
    "modulo": "M12",
    "submodulo": "12.1",
    "editalRef": "Conhecimentos Gerais / Simulado Geral Câmara dos Deputados",
    "nivel": 2,
    "habilidade": "compreender",
    "ehPegadinha": false,
    "fonte": "HNC — textos autorais: AI in parliament e Open parliamentary data — Text I, integral acima do item. Texto ou obra no acervo HNC.",
    "dataConferencia": "2026-10-31",
    "gatilho": "supervisão humana",
    "versao_errada": "O Text I apresenta a IA como solução autônoma que dispensa revisão profissional.",
    "versao_correta": ""
