    "macroModuloId": "M12",
    "submoduloId": "12.1",
    "contexto": "Text II — Open parliamentary data (texto autoral HNC)\n\nPublishing parliamentary agendas and procurement data in structured formats such as JSON or XML can make public information easier to reuse. Yet raw datasets alone do not guarantee civic engagement. People also need clear interfaces, search terms they understand and contextual explanations. Without them, information asymmetries may persist, even when files are public. Transparency must also respect privacy limits: medical records and personal registration data do not become open merely because an office holds them. Open government initiatives should combine reusable data, usable services and protection of rights.",
