    "item": "De acordo com as regras do AACR2r (Capítulo 21), por se tratar de obra de autoria compartilhada entre dois autores sem indicação explícita de responsabilidade principal, a entrada principal deve ser formulada compulsoriamente pelo título da publicação, criando-se entradas secundárias para ambos os autores no campo 700 do formato MARC 21.",
    "gabarito": "E",
    "justificativa": "ERRADO. No caso delimitado, a regra usual é entrada principal pelo primeiro autor mencionado, com entrada secundária pelo outro. Entrada pelo título não é consequência necessária de haver dois autores sem principal. Na codificação MARC, nome pessoal principal é 100 e o adicional pode ser 700.",
    "submoduloId": "2.1",
    "submodulo": "2.1",
    "editalRef": "Conhecimentos Específicos / Caso Integrador CI-1",
    "contexto": "Situação hipotética para os itens de aplicação. [Caso Integrador CI-1 — CI-1: Catalogação, Modelagem LRM e Classificação de Obra sobre Processo Legislativo] A Biblioteca Pedro Aleixo da Câmara dos Deputados adquiriu uma monografia jurídica contemporânea intitulada \"O Devido Processo Legislativo Constitucional e a Tramitação de Proposições no Congresso Nacional\", de autoria de dois docentes de universidade federal sem indicação de autor principal. A obra contempla análise doutrinária do Regimento Interno da Câmara, estudos comparados de direito parlamentar e tabelas sinóticas de prazos de tramitação. O bibliotecário responsável pelo processamento técnico foi incumbido de: (1) realizar a modelagem conceitual e catalogação descritiva da obra segundo o modelo IFLA LRM e as normas RDA e AACR2r; (2) definir os pontos de acesso principais e secundários, transcrevendo os dados no formato MARC 21 Bibliográfico; e (3) atribuir a notação de classificação temática em CDD e CDU, além de termos de indexação a partir do Vocabulário Controlado da Rede Virtual de Bibliotecas (RVBI/BDCam). Considerando essa situação hipotética e os preceitos de catalogação, classificação e modelagem, julgue os itens a seguir.",
