    "gabarito": "C",
    "justificativa": "CERTO. Pessoas são agentes no LRM. Identificadores e vínculos de autoridade podem ajudar a relacionar autores e obras em dados conectados. Converter registros exige também mapeamento e validação; só criar um nome autorizado não produz automaticamente um grafo BIBFRAME correto.",
