    "fonte": "Lei 13.709/2018 — Lei Geral de Proteção de Dados Pessoais — arts. 6º e 7º, §§3º e 4º: dados públicos e finalidade — https://www2.camara.leg.br/legin/fed/lei/2018/lei-13709-14-agosto-2018-787077-normaatualizada-pl.html",
