    "submodulo": "7.1",
    "editalRef": "Conhecimentos Gerais / Simulado Geral Câmara dos Deputados",
    "nivel": 2,
    "habilidade": "compreender",
    "ehPegadinha": true,
    "fonte": "CASSARES, Norma Cianflone. Como fazer conservação preventiva em arquivos e bibliotecas. 2000 — poeira e higienização preventiva. Texto ou obra no acervo HNC.",
    "dataConferencia": "2026-10-31",
    "versao_correta": "Poeira pode favorecer abrasão e degradação e deve ser controlada por higienização adequada.",
    "gatilho": "inofensiva",
