    "fonte": "Creative Commons — About CC Licenses — condições da licença BY-NC-SA e limites do licenciamento — https://creativecommons.org/share-your-work/cclicenses/",
    "id": "geral-180q-142",
    "numero": 142,
    "macroModuloId": "GERAL",
    "modulo": "GERAL",
    "dataConferencia": "2026-10-31",
